import { describe, it, expect, beforeAll, afterEach } from 'vitest';
import { readFileSync } from 'node:fs';
import { createRequire } from 'node:module';
import { resolve } from 'node:path';
import { React, ReactDOMClient, resetStemLab, makeCtx } from './helpers/stem_widgets_smoke_harness.js';

const require = createRequire(import.meta.url);
const { act } = require(resolve(process.cwd(), 'desktop/web-app/node_modules/react-dom/test-utils'));
globalThis.IS_REACT_ACT_ENVIRONMENT = true;

// The Learn page's Practice Round card (builder module). Rounds are generated by the
// core (tests/geometry_world_practice_round.test.js); this card starts a new one at
// the chosen level, continues an unfinished one, plays a round a class shares by its
// number (S42 is stretch round 42), and shows the student's skills by station.
const BUILDER = readFileSync('stem_lab/stem_tool_geometryworld_builder.js', 'utf8');
let cfg;
beforeAll(() => {
  const lab = resetStemLab();
  lab.registerTool('geometryWorld', { aliases: [], render(ctx) {
    return ctx.React.createElement('main', { id: 'geoworld-fs-workspace', className: 'gw-core' },
      ctx.React.createElement('div', { id: 'geoworld-fs-wrap', role: 'application', tabIndex: 0 }, '3D world'));
  } });
  new Function(BUILDER)();
  cfg = lab._registry.geometryWorld;
});
afterEach(() => { delete window.__geoWorldEngine; delete window.StemLab.geometryWorldPractice; document.body.innerHTML = ''; });

function engine() {
  const lesson = { id: 'volumeExplorer', title: 'Volume Explorer', description: 'x', objectives: [], ground: { xMin: 0, xMax: 4, zMin: 0, zMax: 4, y: 0 }, structures: [], activities: [], npcs: [] };
  const en = { blocks: {}, _currentLesson: { ground: {} }, _undoStack: [], _redoStack: [], started: [], geometryHomeLessons: [lesson],
    loadLesson() {}, placeBlock() {}, logEvent() {}, startHomeLesson: () => true };
  en.startPracticeRound = (round, level) => { en.started.push([round, level]); return 77; };
  return en;
}
// The core's own round reader, lifted from the tool, so the card is tested against it.
const CORE = readFileSync('stem_lab/stem_tool_geometryworld.js', 'utf8');
const parseRound = new Function(
  CORE.slice(CORE.indexOf('  function geometryPracticeSeed(value) {'), CORE.indexOf('  // practice_42 is round 42; practice_s42 is stretch round 42.')) +
  CORE.slice(CORE.indexOf('  function geometryPracticeParseRound(text, level) {'), CORE.indexOf('  function geometryPracticeLabel(round)')) +
  'return geometryPracticeParseRound;')();
const noSkills = ['Volume in layers', 'Surface area from nets', 'Missing dimensions', 'Composite shapes'].map((skill, i) => ({ station: 'S' + i, skill, results: [], firstTry: 0, tries: 0 }));
function practiceApi(summary) {
  return { summary: () => Object.assign({ current: '', currentLabel: '', skills: noSkills, focus: '' }, summary), parseRound };
}
function mount(initial) {
  const host = document.createElement('div'); document.body.appendChild(host);
  const root = ReactDOMClient.createRoot(host);
  function Host() {
    const [gw, setGw] = React.useState(initial);
    const ctx = makeCtx({ toolData: { geometryWorld: gw }, updateMulti(_tool, patch) { setGw((previous) => ({ ...previous, ...patch })); } });
    return cfg.render(ctx);
  }
  act(() => root.render(React.createElement(Host)));
  return { host, unmount() { act(() => root.unmount()); host.remove(); } };
}
const click = (el) => act(() => el.dispatchEvent(new window.MouseEvent('click', { bubbles: true })));
const learn = { activeLesson: 'volumeExplorer', worldActive: true, showGeometryHome: true, geometryHomePage: 'learn' };

describe('the Learn page Practice Round card', () => {
  it('starts a new round, and continues an unfinished one where it was left', () => {
    const en = engine(); window.__geoWorldEngine = en;
    window.StemLab.geometryWorldPractice = practiceApi({ rounds: 2, current: 'practice_s42', currentLabel: 'Stretch round 42', answered: 1, total: 4 });
    const view = mount(learn);
    const card = view.host.querySelector('.gwe-home-practice');
    expect(card.querySelector('h2').textContent).toBe('Practice Round');
    expect(card.textContent).toContain('You have finished 2 rounds.');
    const cont = card.querySelector('[data-gwe-practice="continue"]');
    expect(cont.textContent).toBe('Continue stretch round 42 (1 of 4 stations done)');
    click(cont);
    click(card.querySelector('[data-gwe-practice="new"]'));
    expect(en.started).toEqual([['practice_s42', undefined], [undefined, 'core']]);
    view.unmount();
  });

  it('the level switch sets the level of a new round and of a class round', () => {
    const en = engine(); window.__geoWorldEngine = en;
    window.StemLab.geometryWorldPractice = practiceApi({ rounds: 0 });
    const view = mount(learn);
    const card = view.host.querySelector('.gwe-home-practice');
    const level = (id) => card.querySelector('[data-gwe-practice-level="' + id + '"]');
    expect(card.querySelector('[role="group"]').getAttribute('aria-label')).toBe('Practice level');
    expect([level('core').getAttribute('aria-pressed'), level('stretch').getAttribute('aria-pressed')]).toEqual(['true', 'false']);
    click(level('stretch'));
    expect([level('core').getAttribute('aria-pressed'), level('stretch').getAttribute('aria-pressed')]).toEqual(['false', 'true']);
    expect(card.querySelector('[data-gwe-practice="new"]').textContent).toBe('Start a new stretch round');
    click(card.querySelector('[data-gwe-practice="new"]'));
    const input = card.querySelector('#gwe-home-practice-round');
    Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set.call(input, '15');
    act(() => input.dispatchEvent(new window.Event('input', { bubbles: true })));
    act(() => card.querySelector('.gwe-home-practice-join').dispatchEvent(new window.Event('submit', { bubbles: true, cancelable: true })));
    click(level('core'));
    Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set.call(input, 'S9');
    act(() => input.dispatchEvent(new window.Event('input', { bubbles: true })));
    act(() => card.querySelector('.gwe-home-practice-join').dispatchEvent(new window.Event('submit', { bubbles: true, cancelable: true })));
    // S9 is stretch round 9 whatever the switch says; 15 follows the switch.
    expect(en.started).toEqual([[undefined, 'stretch'], [15, 'stretch'], [9, 'stretch']]);
    view.unmount();
  });

  it('shows each practised skill with its recent results, in words as well as dots, and what to focus on', () => {
    window.__geoWorldEngine = engine();
    const skills = noSkills.map((s) => Object.assign({}, s));
    skills[0] = Object.assign(skills[0], { results: [true, true, false], firstTry: 2, tries: 3 });
    skills[1] = Object.assign(skills[1], { results: [false], firstTry: 0, tries: 1 });
    window.StemLab.geometryWorldPractice = practiceApi({ rounds: 3, skills, focus: 'Surface area from nets' });
    const view = mount(learn);
    const box = view.host.querySelector('.gwe-home-practice-skills');
    expect(box.querySelector('h3').textContent).toBe('Your practice skills');
    const rows = [...box.querySelectorAll('li')];
    expect(rows.map((r) => r.querySelector('.gwe-home-skill-name').textContent)).toEqual(['Volume in layers', 'Surface area from nets']);
    expect(rows.map((r) => r.querySelector('.gwe-home-skill-count').textContent)).toEqual(['2 of the last 3 right first time', 'Took another try']);
    expect(rows[0].querySelector('.gwe-home-skill-dots').getAttribute('aria-hidden')).toBe('true');
    expect([...rows[0].querySelectorAll('.gwe-home-skill-dots i')].map((i) => i.getAttribute('data-ok'))).toEqual(['true', 'true', 'false']);
    expect(box.querySelector('.gwe-home-practice-focus').textContent).toBe('Focus next: Surface area from nets.');
    view.unmount();
    // Nothing practised yet: no empty skills box.
    window.StemLab.geometryWorldPractice = practiceApi({ rounds: 0 });
    const fresh = mount(learn);
    expect(fresh.host.querySelector('.gwe-home-practice-skills')).toBeNull();
    fresh.unmount();
  });

  it('plays a class round by its number, and explains a number it cannot use', () => {
    const en = engine(); window.__geoWorldEngine = en;
    window.StemLab.geometryWorldPractice = practiceApi({ rounds: 0, answered: 0, total: 4 });
    const view = mount(learn);
    const card = view.host.querySelector('.gwe-home-practice');
    expect(card.querySelector('[data-gwe-practice="continue"]')).toBeNull();
    expect(card.textContent).not.toContain('You have finished');
    const input = card.querySelector('#gwe-home-practice-round');
    expect(card.querySelector('label[for="gwe-home-practice-round"]').textContent).toMatch(/round with your class/);
    const type = (text) => {
      Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set.call(input, text);
      act(() => input.dispatchEvent(new window.Event('input', { bubbles: true })));
      act(() => card.querySelector('.gwe-home-practice-join').dispatchEvent(new window.Event('submit', { bubbles: true, cancelable: true })));
    };
    type('abc');
    expect(card.querySelector('[role="alert"]').textContent).toBe('Type a round number from 1 to 9999, or S and a number for a stretch round.');
    expect(input.getAttribute('aria-invalid')).toBe('true');
    expect(input.getAttribute('aria-describedby')).toBe('gwe-home-practice-error');
    expect(en.started).toEqual([]);
    type('4821');
    expect(en.started).toEqual([[4821, 'core']]);
    view.unmount();
  });

  it('is offered only on the Learn page, and only when the core provides rounds', () => {
    window.__geoWorldEngine = engine();
    let view = mount(learn);
    expect(view.host.querySelector('.gwe-home-practice')).toBeNull();
    view.unmount();
    window.StemLab.geometryWorldPractice = practiceApi({ rounds: 0 });
    view = mount(Object.assign({}, learn, { geometryHomePage: 'explore' }));
    expect(view.host.querySelector('.gwe-home-practice')).toBeNull();
    view.unmount();
  });

  it('the buttons wait for the world to be ready', () => {
    const en = engine(); delete en.startPracticeRound; window.__geoWorldEngine = en;
    window.StemLab.geometryWorldPractice = practiceApi({ rounds: 0 });
    const view = mount(learn);
    expect(view.host.querySelector('[data-gwe-practice="new"]').disabled).toBe(true);
    view.unmount();
  });
});
